fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val k = st.nextToken().toInt()

    if (k == 1) {
        // Only permutation [1..n] returns n; all others are faulty
        var fact = 1L
        for (i in 2..n) fact = (fact * i) % MOD
        val ans = (fact - 1 + MOD) % MOD
        println(ans)
        return
    }

    val maxNK = maxOf(n, k)
    val fact = LongArray(maxNK + 1)
    val invFact = LongArray(maxNK + 1)
    fact[0] = 1L
    for (i in 1..maxNK) fact[i] = (fact[i - 1] * i) % MOD
    invFact[maxNK] = modPow(fact[maxNK], MOD - 2)
    for (i in maxNK downTo 1) {
        invFact[i - 1] = (invFact[i] * i) % MOD
    }

    fun comb(a: Int, b: Int): Long {
        if (b < 0 || b > a) return 0L
        return (((fact[a] * invFact[b]) % MOD) * invFact[a - b]) % MOD
    }

    // dp[t] = number of permutations of {1..t} where maximum is reached at position t
    // and last k elements contain no new maximum (i.e., max at t, and t is in last k positions)
    val dp = LongArray(n + 1)
    dp[0] = 1L
    var sum = 1L // prefix sum of dp
    var ans = 0L

    for (t in 1..n) {
        // dp[t] = sum_{i=max(0, t-k)}^{t-1} dp[i]
        val left = t - k
        val sub = if (left - 1 >= 0) dp[left - 1] else 0L
        dp[t] = (sum - sub + MOD) % MOD
        sum = (sum + dp[t]) % MOD

        // t must be in last k positions: t >= n-k+1
        if (t >= n - k + 1) {
            val remaining = n - t
            val ways = (dp[t] * fact[remaining]) % MOD
            ans = (ans + ways) % MOD
        }
    }

    // total permutations
    var total = 1L
    for (i in 2..n) total = (total * i) % MOD

    // correct permutations = ans
    // faulty = total - correct
    val res = (total - ans + MOD) % MOD
    println(res)
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD: Long = 1_000_000_007L

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val k = st.nextToken().toInt()

    if (k == 1) {
        // Only permutation [n, n-1, ..., 1] returns n
        // All others (n! - 1) are faulty
        val fact = LongArray(n + 1)
        fact[0] = 1
        for (i in 1..n) fact[i] = fact[i - 1] * i % MOD
        val ans = (fact[n] - 1 + MOD) % MOD
        println(ans)
        return
    }

    val maxNK = maxOf(n, k)
    val fact = LongArray(maxNK + 1)
    val invFact = LongArray(maxNK + 1)
    fact[0] = 1
    for (i in 1..maxNK) fact[i] = fact[i - 1] * i % MOD
    invFact[maxNK] = modPow(fact[maxNK], MOD - 2)
    for (i in maxNK downTo 1) {
        invFact[i - 1] = invFact[i] * i % MOD
    }

    fun comb(a: Int, b: Int): Long {
        if (b < 0 || b > a) return 0
        return fact[a] * invFact[b] % MOD * invFact[a - b] % MOD
    }

    // dp[t] = number of permutations of {1..t} where fast_max returns t
    val dp = LongArray(n + 1)
    dp[0] = 0
    if (n >= 1) dp[1] = 1

    for (t in 2..n) {
        var sum = 0L
        val limit = minOf(k - 1, t - 1)
        for (i in 0..limit) {
            val ways = comb(t - 1, i)
            val term = ways * fact[t - 1 - i] % MOD
            sum += term
            if (sum >= MOD) sum -= MOD
        }
        dp[t] = sum
    }

    // Number of permutations where fast_max returns n is dp[n]
    // Faulty permutations = n! - dp[n]
    val ans = (fact[n] - dp[n] + MOD) % MOD
    println(ans)
}

private fun modPow(base: Long, exp: Long): Long {
    var b = base % MOD
    var e = exp
    var res = 1L
    while (e > 0) {
        if ((e and 1L) != 0L) res = res * b % MOD
        b = b * b % MOD
        e = e shr 1
    }
    return res
}
